def b_transform(slide_mm, descent_mm=0.0):
    s,d = finite(slide_mm),finite(descent_mm)
    if not 0 <= s <= 79.75 or not 0 <= d <= 8.2:
        raise ValueError('outside native B travel')
    if d > 0 and s != 79.75:
        raise ValueError('normal seating requires full slide')
    return (0.0,s,8.2-d)

